{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-9d20fd1f16e774c0","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t\n21\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n22\t\n23\tUsage:\n24\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n25\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n26\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n27\t\"\"\"\n28\t\n29\timport argparse\n30\timport os\n31\timport re\n32\timport sys\n33\t\n34\timport yaml\n35\t\n36\tSECTIONS = [(\"Description\", (\"description\",)),\n37\t            (\"Scope\", (\"scope\",)),\n38\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n39\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n40\t\n41\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n42\t\n43\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n44\t\n45\t\n46\tdef read_frontmatter(path):\n47\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n48\t    with open(path, encoding=\"utf-8\") as f:\n49\t        content = f.read()\n50\t    m = FRONTMATTER_RE.match(content)\n51\t    if not m:\n52\t        return {}, content\n53\t    try:\n54\t        data = yaml.safe_load(m.group(1))\n55\t    except yaml.YAMLError:\n56\t        return {}, content\n57\t    if not isinstance(data, dict):\n58\t        return {}, content\n59\t    return data, content[m.end():]\n60\t\n61\t\n62\tdef body_headings(body):\n63\t    heads = []\n64\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n65\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n66\t    return heads\n67\t\n68\t\n69\tdef load_epics(artifacts_dir, strat_id):\n70\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n71\t\n72\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n73\t    \"\"\"\n74\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n75\t    if not os.path.isdir(task_dir):\n76\t        return {}\n77\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n78\t    epics = {}\n79\t    for name in sorted(os.listdir(task_dir)):\n80\t        m = pat.match(name)\n81\t        if not m:\n82\t            continue\n83\t        path = os.path.join(task_dir, name)\n84\t        fm, body = read_frontmatter(path)\n85\t        epics[name[:-3]] = (path, fm, body)\n86\t    return epics\n87\t\n88\t\n89\tdef dependency_closure(start_key, deps):\n90\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n91\t    seen, stack = set(), list(deps.get(start_key, []))\n92\t    while stack:\n93\t        n = stack.pop()\n94\t        if n in seen or n not in deps:\n95\t            continue\n96\t        seen.add(n)\n97\t        stack.extend(deps[n])\n98\t    return seen\n99\t\n100\t\n101\tdef check(strat_id, artifacts_dir, components_path):\n102\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n103\t    probs = []\n104\t    epics = load_epics(artifacts_dir, strat_id)\n105\t    if not epics:\n106\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n107\t                % (strat_id, artifacts_dir)]\n108\t\n109\t    valid_components = set()\n110\t    if os.path.isfile(components_path):\n111\t        with open(components_path, encoding=\"utf-8\") as f:\n112\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n113\t    if not valid_components:\n114\t        probs.append(\"cannot read canonical component list %s — verify the \"\n115\t                     \"path before trusting component names\" % components_path)\n116\t\n117\t    deps, is_branch, is_docs, is_impl, prio = {}, {}, {}, {}, {}\n118\t    for key, (path, fm, body) in epics.items():\n119\t        name = key + \".md\"\n120\t        # 1. body sections (contract parity with the artifact judge)\n121\t        heads = body_headings(body)\n122\t        for want, aliases in SECTIONS:\n123\t            if not any(a in h for h in heads for a in aliases):\n124\t                probs.append(\"%s: body missing '%s' section (required \"\n125\t                             \"sections: Description, Scope, Acceptance \"\n126\t                             \"Criteria, HLR Traceability)\" % (name, want))\n127\t        # 2. component vocabulary\n128\t        comp = fm.get(\"component\")\n129\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n130\t                and comp.strip() not in valid_components:\n131\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n132\t                         \"canonical name (submit.py strips unknown names)\"\n133\t                         % (name, comp.strip(), components_path))\n134\t        # collect graph facts\n135\t        dl = fm.get(\"dependencies\")\n136\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n137\t            if isinstance(dl, list) else []\n138\t        is_branch[key] = \"BRANCH-\" in key\n139\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n140\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n141\t        prio[key] = fm.get(\"priority\")\n142\t\n143\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n144\t    universe = [k for k in epics\n145\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n146\t    for k in sorted(epics):\n147\t        if not is_docs[k]:\n148\t            continue\n149\t        cl = dependency_closure(k, deps)\n150\t        missing = sorted(e for e in universe if e != k and e not in cl)\n151\t        if missing:\n152\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n153\t                         \"Implementation epic — add %s to its dependency chain\"\n154\t                         % (k, \", \".join(missing)))\n155\t\n156\t    # 4. Priority inheritance — enablers of P0 work must be P0\n157\t    for k in sorted(epics):\n158\t        if is_branch[k] or is_docs[k]:\n159\t            continue\n160\t        if prio.get(k) != \"P0\":\n161\t            continue\n162\t        # every main-plan, non-docs epic in k's closure enables P0 work\n163\t        cl = dependency_closure(k, deps)\n164\t        for t in sorted(cl):\n165\t            if is_branch[t] or is_docs[t]:\n166\t                continue\n167\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n168\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n169\t                             \"but is %s — raise it to P0 or restructure\"\n170\t                             % (t, prio.get(t), k, prio.get(t)))\n171\t    return probs\n172\t\n173\t\n174\t# ─── self-check ───────────────────────────────────────────────────────────────\n175\t\n176\tdef _self_check():\n177\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n178\t    import shutil\n179\t    import tempfile\n180\t\n181\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n182\t    try:\n183\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n184\t        os.makedirs(art)\n185\t        comp = os.path.join(tmp, \"components.txt\")\n186\t        with open(comp, \"w\") as f:\n187\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n188\t\n189\t        def write(name, fm, body):\n190\t            with open(os.path.join(art, name), \"w\") as f:\n191\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n192\t\n193\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n194\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n195\t        write(\"RHAISTRAT-9001-E001.md\",\n196\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n197\t              \"dependencies: []\\n\", good_body)\n198\t        write(\"RHAISTRAT-9001-E002.md\",\n199\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n200\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n201\t              \"dependencies: [RHAISTRAT-9001-E001]\\n\", good_body)\n202\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n203\t                     comp) == [], \"good fixture must pass cleanly\"\n204\t\n205\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge\n206\t        write(\"RHAISTRAT-9002-E001.md\",\n207\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n208\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n209\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n210\t              \"## HLR Traceability\\nh\\n\")\n211\t        write(\"RHAISTRAT-9002-E002.md\",\n212\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n213\t              \"dependencies: []\\n\", good_body)\n214\t        write(\"RHAISTRAT-9002-E003.md\",\n215\t              \"component: Dashboard\\ntype: Implementation\\n\"\n216\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n217\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n218\t        # E004 is a main-plan Implementation the docs epic never depends on\n219\t        write(\"RHAISTRAT-9002-E004.md\",\n220\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n221\t              \"dependencies: []\\n\", good_body)\n222\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n223\t        joined = \"\\n\".join(probs)\n224\t        assert \"missing 'Scope'\" in joined, probs\n225\t        assert \"Model Serving Stack\" in joined, probs\n226\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n227\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n228\t        print(\"self-check OK: 4 checks fire on bad fixture, clean on good\")\n229\t        return 0\n230\t    finally:\n231\t        shutil.rmtree(tmp, ignore_errors=True)\n232\t\n233\t\n234\tdef main(argv=None):\n235\t    ap = argparse.ArgumentParser(description=__doc__)\n236\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n237\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n238\t    ap.add_argument(\"--components\",\n239\t                    default=\".context/rhai-components.txt\")\n240\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n241\t    args = ap.parse_args(argv)\n242\t\n243\t    if args.self_check:\n244\t        return _self_check()\n245\t    if not args.strat_id:\n246\t        ap.error(\"strat_id is required (unless --self-check)\")\n247\t\n248\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n249\t    if probs:\n250\t        for p in probs:\n251\t            print(\"VIOLATION: %s\" % p)\n252\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n253\t              \"complete\" % len(probs))\n254\t        return 1\n255\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n256\t    return 0\n257\t\n258\t\n259\tif __name__ == \"__main__\":\n260\t    sys.exit(main())\n261\t"}]},"parent_tool_use_id":"chatcmpl-tool-8b305912d97c92d7","agent_id":"a6d2ecbd0d01bdd6b","session_id":"98e9d94a-7db9-4011-b4e9-ddd4548bd187","uuid":"57e6d775-efd1-46fa-b94f-d4fdd9e8f83f","timestamp":"2026-10-22T14:15:21.127Z","tool_result_meta":[{"id":"chatcmpl-tool-9d20fd1f16e774c0","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Revise RHAISTRAT-9008 decomposition"}
